import{_ as a,o as t,c as l,ae as s}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Pallet Storage","description":"","frontmatter":{"title":"Pallet Storage"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md"}'),o={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/palletstorage.md"};function r(n,e,i,p,d,h){return t(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="pallet-storage" tabindex="-1">Pallet Storage <a class="header-anchor" href="#pallet-storage" aria-label="Permalink to &quot;Pallet Storage&quot;">​</a></h1><p>Pallet Storage is a storage building used to store <strong>Pallets</strong>, allowing players to keep large quantities of pallets without needing to leave them around their farm or keep them loaded on trailers.</p><p>Pallet Storage is particularly useful for players involved in production chains where large quantities of products are produced and need to be stored before being transported or sold.</p><h2 id="building-information" tabindex="-1">Building Information <a class="header-anchor" href="#building-information" aria-label="Permalink to &quot;Building Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Building</td><td>Pallet Storage</td></tr><tr><td>Purpose</td><td>Pallet Storage</td></tr><tr><td>Capacity</td><td><strong>To be confirmed</strong></td></tr><tr><td>Storage Type</td><td>Pallets</td></tr><tr><td>Build Menu</td><td>Create &gt; Buildings</td></tr></tbody></table><h2 id="stored-pallets" tabindex="-1">Stored Pallets <a class="header-anchor" href="#stored-pallets" aria-label="Permalink to &quot;Stored Pallets&quot;">​</a></h2><p>Pallet Storage can be used to store compatible pallets containing produced goods.</p><p>These may include pallets produced by factories and other production buildings.</p><p>The storage is designed for pallets rather than loose crops, liquids, or logs.</p><h2 id="how-to-use-pallet-storage" tabindex="-1">How to Use Pallet Storage <a class="header-anchor" href="#how-to-use-pallet-storage" aria-label="Permalink to &quot;How to Use Pallet Storage&quot;">​</a></h2><h3 id="_1-purchase-the-storage" tabindex="-1">1. Purchase the Storage <a class="header-anchor" href="#_1-purchase-the-storage" aria-label="Permalink to &quot;1. Purchase the Storage&quot;">​</a></h3><p>Open the <strong>Create</strong> menu and purchase the Pallet Storage.</p><p>Place the storage somewhere accessible to your farm and transport vehicles.</p><h3 id="_2-load-pallets" tabindex="-1">2. Load Pallets <a class="header-anchor" href="#_2-load-pallets" aria-label="Permalink to &quot;2. Load Pallets&quot;">​</a></h3><p>Bring completed pallets to the Pallet Storage using a suitable vehicle or trailer.</p><p>Unload the pallets into the storage area.</p><p>The pallets will be added to the available storage.</p><h3 id="_3-store-pallets" tabindex="-1">3. Store Pallets <a class="header-anchor" href="#_3-store-pallets" aria-label="Permalink to &quot;3. Store Pallets&quot;">​</a></h3><p>Once the pallets have been deposited, they remain stored inside the Pallet Storage until they are needed.</p><p>The storage capacity is currently <strong>to be confirmed</strong>.</p><h3 id="_4-remove-pallets" tabindex="-1">4. Remove Pallets <a class="header-anchor" href="#_4-remove-pallets" aria-label="Permalink to &quot;4. Remove Pallets&quot;">​</a></h3><p>When you need the stored pallets for transportation or selling, use a suitable vehicle or trailer at the storage&#39;s loading area.</p><p>The stored pallets can then be transferred onto the vehicle for transportation.</p><h2 id="pallet-storage-chain" tabindex="-1">Pallet Storage Chain <a class="header-anchor" href="#pallet-storage-chain" aria-label="Permalink to &quot;Pallet Storage Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Factory</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Pallet</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>Pallet Storage</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Transport      Sell</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Destination   Sell Point</span></span></code></pre></div><h2 id="uses" tabindex="-1">Uses <a class="header-anchor" href="#uses" aria-label="Permalink to &quot;Uses&quot;">​</a></h2><p>Pallet Storage is especially useful for:</p><ul><li>Storing produced pallets</li><li>Building up large quantities of products</li><li>Storing products between production runs</li><li>Reducing the need for multiple trailers</li><li>Preparing products for transportation</li><li>Keeping produced goods organised on your farm</li></ul><blockquote><p><strong>Tip:</strong> Pallet Storage is particularly useful when running factories that produce large quantities of palletised products, allowing finished goods to be stored until you are ready to transport or sell them.</p></blockquote><blockquote><p><strong>Note:</strong> Storage prices, capacities, supported pallets, and functionality may change with future game updates.</p></blockquote>`,30)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
